create table if not exists profiles (id uuid primary key references auth.users(id), nombre text not null, email text not null, rol text not null default 'empleado', activo boolean default true, created_at timestamptz default now());
create table if not exists products (id uuid primary key default gen_random_uuid(), codigo text not null unique, nombre text not null, categoria text not null, precio_local numeric default 0, precio_whatsapp numeric default 0, precio_didi numeric default 0, precio_uber numeric default 0, costo_base numeric default 0, activo boolean default true, created_at timestamptz default now());
create table if not exists ingredients (id uuid primary key default gen_random_uuid(), nombre text not null, unidad text not null, stock_actual numeric default 0, stock_minimo numeric default 0, costo_unitario numeric default 0, proveedor text, created_at timestamptz default now());
create table if not exists recipes (id uuid primary key default gen_random_uuid(), product_id uuid references products(id) on delete cascade, ingredient_id uuid references ingredients(id) on delete cascade, cantidad numeric not null);
create table if not exists sales (id uuid primary key default gen_random_uuid(), fecha_operativa date not null, fecha_real timestamptz default now(), canal text not null, metodo_pago text not null, subtotal numeric default 0, costo_total numeric default 0, iva numeric default 0, resico numeric default 0, comision numeric default 0, utilidad_real numeric default 0, no_tocar numeric default 0, user_id uuid references profiles(id), created_at timestamptz default now());
create table if not exists sale_items (id uuid primary key default gen_random_uuid(), sale_id uuid references sales(id) on delete cascade, product_id uuid references products(id), cantidad numeric default 1, precio_unitario numeric default 0, costo_unitario numeric default 0, salsa text, notas text);
create table if not exists expenses (id uuid primary key default gen_random_uuid(), categoria text not null, monto numeric not null, descripcion text, fecha date default current_date, user_id uuid references profiles(id), created_at timestamptz default now());
create table if not exists cash_sessions (id uuid primary key default gen_random_uuid(), fecha_operativa date not null, apertura timestamptz default now(), cierre timestamptz, fondo_inicial numeric default 0, efectivo_esperado numeric default 0, efectivo_real numeric default 0, diferencia numeric default 0, user_id uuid references profiles(id));
create table if not exists settings (id uuid primary key default gen_random_uuid(), iva numeric default 16, resico numeric default 6.25, reinversion numeric default 20, sueldo numeric default 15, gastos_fijos numeric default 10, comision_didi numeric default 30, comision_uber numeric default 35, created_at timestamptz default now());
create table if not exists inventory_movements (id uuid primary key default gen_random_uuid(), ingredient_id uuid references ingredients(id), tipo text not null, cantidad numeric not null, motivo text, sale_id uuid references sales(id), expense_id uuid references expenses(id), created_at timestamptz default now());
