create or replace function decrement_stock(ingredient_id uuid, amount numeric) returns void as $$ update ingredients set stock_actual = stock_actual - amount where id = ingredient_id; $$ language sql;
create or replace function increment_stock(ingredient_id uuid, amount numeric) returns void as $$ update ingredients set stock_actual = stock_actual + amount where id = ingredient_id; $$ language sql;
alter table profiles enable row level security; alter table products enable row level security; alter table ingredients enable row level security; alter table recipes enable row level security; alter table sales enable row level security; alter table sale_items enable row level security; alter table expenses enable row level security; alter table cash_sessions enable row level security; alter table settings enable row level security; alter table inventory_movements enable row level security;
create policy "read products" on products for select to authenticated using (true);
create policy "read ingredients" on ingredients for select to authenticated using (true);
create policy "insert sales" on sales for insert to authenticated with check (true);
create policy "read sales" on sales for select to authenticated using (true);
create policy "insert sale_items" on sale_items for insert to authenticated with check (true);
create policy "read sale_items" on sale_items for select to authenticated using (true);
create policy "read settings" on settings for select to authenticated using (true);
